row_rules.ST_TRNS_MAST:
if app_rules_pr.bypass = 0 and app_rules_pr.is_purchase_type(:new.trns_type_code) = 1 then
  -- purchase invoices / returns (ST_RECEIVE_COST, ST_RETURN_COST, ST_RETURN_COST2): legacy PRE-INSERT and WVI derivations
  if inserting then
    :new.delete_flag := nvl(:new.delete_flag, 0);
    :new.entry_date := nvl(:new.entry_date, trunc(sysdate));
    :new.store_code := nvl(:new.store_code, app_rules_pr.type_store(:new.trns_type_code));
    if :new.supplier_code is not null then
      if nvl(:new.currency_code, 1) = 1 and app_rules_pr.supplier_currency(:new.supplier_code) <> 1 then
        :new.currency_code := app_rules_pr.supplier_currency(:new.supplier_code);
        :new.currency_rate := app_rules_pr.currency_rate(:new.currency_code, :new.trns_date);
      end if;
      :new.purch_code := nvl(:new.purch_code, app_rules_pr.supplier_resp(:new.supplier_code));
      :new.gln := nvl(:new.gln, app_rules_pr.supplier_gln(:new.supplier_code));
    end if;
    :new.posting_supplier_code := nvl(:new.posting_supplier_code, :new.supplier_code);
    if app_rules_pr.is_receive_type(:new.trns_type_code) = 1 then
      :new.invoice_no := nvl(:new.invoice_no, to_char(:new.trns_type_code) || lpad(to_char(:new.trns_serial), 7, '0'));
    else
      :new.invoice_no := nvl(:new.invoice_no, app_rules_pr.st_invoice_no(:new.ret_trns_type_code, :new.ret_trns_serial));
      :new.doc_no := nvl(:new.doc_no, app_rules_pr.next_st_doc_no(:new.trns_type_code, :new.store_code));
    end if;
  elsif app_rules_pr.chg(:new.supplier_code, :old.supplier_code) = 1 then
    :new.posting_supplier_code := :new.supplier_code;
  end if;
  if (inserting and :new.due_date is null and :new.due_days is not null)
     or (updating and app_rules_pr.chg(:new.due_days, :old.due_days) = 1 and app_rules_pr.chg(:new.due_date, :old.due_date) = 0) then
    :new.due_date := :new.trns_date + :new.due_days;
  elsif :new.due_date is not null then
    :new.due_days := trunc(:new.due_date) - trunc(:new.trns_date);
  end if;
end if;

row_rules.ST_TRNS_DET:
if app_rules_pr.bypass = 0 and app_rules_pr.is_purchase_type(:new.trns_type_code) = 1 then
  -- purchase invoice / return lines: group, unit, bonus and discount pairs, basic quantity, price in riyal, lot configuration
  if :new.item_code is not null then
    :new.group_code := nvl(:new.group_code, app_rules_pr.item_group(:new.item_code));
    :new.unit_code := nvl(:new.unit_code, app_rules_pr.basic_unit(:new.group_code, :new.item_code));
  end if;
  if (inserting or app_rules_pr.chg(:new.quantity, :old.quantity) + app_rules_pr.chg(:new.bonus, :old.bonus)
                   + app_rules_pr.chg(:new.extra_bonus, :old.extra_bonus) > 0)
     and (nvl(:new.quantity, 0) < 0 or nvl(:new.quantity, 0) + nvl(:new.bonus, 0) + nvl(:new.extra_bonus, 0) <= 0) then
    raise_application_error(-20122, 'يجب إدخال كمية أكبر من الصفر - الصنف ' || :new.item_code);
  end if;
  if :new.unit_price_curr < 0 then
    raise_application_error(-20122, 'القيمة يجب أن تكون أكبر من الصفر - سعر الصنف ' || :new.item_code);
  end if;
  :new.unit_price_curr := round(:new.unit_price_curr, 4);
  app_rules_pr.pair_ratio(inserting, :new.quantity, :old.quantity, :new.bonus_ratio, :old.bonus_ratio, :new.bonus, :old.bonus);
  app_rules_pr.pair_ratio(inserting, :new.quantity, :old.quantity, :new.extra_bonus_ratio, :old.extra_bonus_ratio, :new.extra_bonus, :old.extra_bonus);
  app_rules_pr.disc_chain(inserting, :new.unit_price_curr, :old.unit_price_curr,
                          :new.disc1_ratio, :old.disc1_ratio, :new.disc1_value, :old.disc1_value,
                          :new.disc2_ratio, :old.disc2_ratio, :new.disc2_value, :old.disc2_value,
                          :new.disc3_ratio, :old.disc3_ratio, :new.disc3_value, :old.disc3_value);
  :new.basic_qty := (nvl(:new.quantity, 0) + nvl(:new.bonus, 0) + nvl(:new.extra_bonus, 0))
                    * app_rules_pr.unit_factor(:new.group_code, :new.item_code, :new.unit_code);
  :new.cost_flag := nvl(:new.cost_flag, 1);
  if :new.unit_price_curr is not null and (inserting or app_rules_pr.chg(:new.unit_price_curr, :old.unit_price_curr) = 1) then
    :new.unit_price := :new.unit_price_curr * app_rules_pr.st_rate(:new.trns_type_code, :new.trns_serial);
  end if;
  if inserting and app_rules_pr.is_receive_type(:new.trns_type_code) = 1 then
    if :new.item_confg_id is null then
      -- line typed on the purchase-invoice page (processes that create invoices supply the lot configuration themselves)
      if :new.unit_price_curr is null then
        raise_application_error(-20122, 'القيمة يجب أن تكون أكبر من الصفر - سعر الصنف ' || :new.item_code);
      end if;
      :new.item_confg_id := app_rules_pr.receive_line_confg(:new.trns_type_code, :new.trns_serial, :new.group_code, :new.item_code,
                              :new.unit_code, :new.lot_number, :new.expiry_date, :new.sales_price, :new.sales_disc_ratio, :new.production_date);
      app_rules_pr.check_next_posted(:new.trns_type_code, :new.trns_serial, :new.group_code, :new.item_code);
    end if;
    if :new.unit_cost is null and nvl(:new.basic_qty, 0) <> 0 then
      :new.unit_cost := ((nvl(:new.quantity, 0) * (nvl(:new.unit_price_curr, 0) - nvl(:new.disc1_value, 0) - nvl(:new.disc2_value, 0)
                          - nvl(:new.disc3_value, 0) - nvl(:new.supp_disc_value, 0))) * app_rules_pr.st_rate(:new.trns_type_code, :new.trns_serial)
                         - nvl(:new.det_disc, 0)) / :new.basic_qty;
    end if;
  end if;
end if;

row_rules.ST_TRNS_DET_DUES:
if app_rules_pr.bypass = 0 and app_rules_pr.is_purchase_type(:new.trns_type_code) = 1 then
  -- ST_TRNS_DET_DUES PRE-INSERT / SUPP_DUE_DATE WVI / AMOUNT_CURR WVI
  if inserting or app_rules_pr.chg(:new.supp_due_date, :old.supp_due_date) = 1 then
    :new.posting_supp_due_date := :new.supp_due_date;
  end if;
  if inserting or app_rules_pr.chg(:new.amount_curr, :old.amount_curr) = 1 then
    :new.amount := :new.amount_curr * app_rules_pr.st_rate(:new.trns_type_code, :new.trns_serial);
  end if;
  :new.payed_flag := nvl(:new.payed_flag, 0);
end if;

row_rules.ST_TRNS_DET_EXPENS:
if app_rules_pr.bypass = 0 and app_rules_pr.is_purchase_type(:new.trns_type_code) = 1 then
  -- ST_TRNS_DET_EXPENS CURRENCY_RATE WVI
  :new.currency_code := nvl(:new.currency_code, 1);
  :new.currency_rate := nvl(:new.currency_rate, 1);
  if :new.currency_rate <= 0 then
    raise_application_error(-20126, 'يجب ادخال معامل التحويل');
  end if;
  if :new.currency_code = 1 and :new.currency_rate <> 1 then
    raise_application_error(-20126, 'معامل تحويل الريال يجب ان يكون ب 1');
  end if;
end if;
